package com.tekwatt.notification.service;import com.tekwatt.notification.dto.*;import com.tekwatt.notification.entity.*;import com.tekwatt.notification.repository.NotificationRepository;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
@Service @Transactional public class NotificationService{private final NotificationRepository repo;public NotificationService(NotificationRepository r){repo=r;}public NotificationResponse create(CreateNotificationRequest r){Optional<Notification>existing=repo.findByIdempotencyKey(r.idempotencyKey());if(existing.isPresent())return NotificationResponse.from(existing.get());return NotificationResponse.from(repo.save(new Notification(r.tenantId(),r.userId(),r.idempotencyKey(),r.channel(),r.recipient(),r.subject(),r.body(),r.templateKey(),r.maxAttempts()==null?3:r.maxAttempts())));}@Transactional(readOnly=true)public NotificationResponse get(UUID id){return NotificationResponse.from(find(id));}@Transactional(readOnly=true)public List<NotificationResponse>list(UUID tenantId){return repo.findAllByTenantIdOrderByCreatedAtDesc(tenantId).stream().map(NotificationResponse::from).toList();}public NotificationResponse send(UUID id){Notification n=find(id);if(n.getStatus()!=NotificationStatus.QUEUED)throw new ResponseStatusException(HttpStatus.CONFLICT,"Notification is not queued");try{n.sending();}catch(IllegalStateException e){bad(e);}return NotificationResponse.from(n);}public NotificationResponse result(UUID id,DeliveryResultRequest r){Notification n=find(id);if(n.getStatus()!=NotificationStatus.SENDING)throw new ResponseStatusException(HttpStatus.CONFLICT,"Notification is not being sent");if(r.successful())n.sent(r.providerMessageId());else n.failed(r.error());return NotificationResponse.from(n);}public NotificationResponse retry(UUID id){Notification n=find(id);if(n.getStatus()!=NotificationStatus.FAILED)throw new ResponseStatusException(HttpStatus.CONFLICT,"Only failed notifications can be retried");try{n.retry();}catch(IllegalStateException e){bad(e);}return NotificationResponse.from(n);}private void bad(IllegalStateException e){throw new ResponseStatusException(HttpStatus.CONFLICT,e.getMessage());}private Notification find(UUID id){return repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Notification not found"));}}
